mapper.sql:
NVL(t.is_deleted, 0) = 0
AND t.user_id = #{userId}

    AND (
        t.title LIKE '%' || #{keyword} || '%'
        OR t.content LIKE '%' || #{keyword} || '%'
        OR t.purpose LIKE '%' || #{keyword} || '%'
    )


    AND t.category = #{category}


    AND t.purpose = #{purpose}


    AND EXISTS (
        SELECT 1
        FROM template_channel tc
        JOIN channel c ON c.id = tc.channel_id
        WHERE tc.template_id = t.id
          AND NVL(tc.is_deleted, 0) = 0
          AND NVL(c.is_deleted, 0) = 0
          AND c.channel_type = #{channelType}
    )

mapper.select:
SELECT tc.template_id, c.id AS channel_id, c.channel_type FROM template_channel tc JOIN channel c ON c.id = tc.channel_id WHERE tc.template_id IN
#{templateId}
AND NVL(tc.is_deleted, 0) = 0 AND NVL(c.is_deleted, 0) = 0 ORDER BY c.channel_type ASC

mapper.insert:
INSERT INTO template ( title, content, kakao_template_code, kakao_template_status, is_ai_generated, category, purpose, user_id,
) VALUES ( #{title}, #{content}, #{kakaoTemplateCode}, #{kakaoTemplateStatus}, #{isAiGenerated}, #{category}, #{purpose}, #{userId},
)

mapper.update:
UPDATE template
SET is_deleted = 1,

WHERE id = #{id}
  AND user_id = #{userId}
  AND NVL(is_deleted, 0) = 0

